'use strict';
const tracks=[{id:0,title:'Soft Landing',artist:'Melora Studio',mood:'Chill',word:'daydream'},{id:1,title:'After Hours',artist:'Melora Studio',mood:'Focus',word:'after hours'},{id:2,title:'Golden Hour',artist:'Melora Studio',mood:'Chill',word:'golden'},{id:3,title:'Blue Motion',artist:'Melora Studio',mood:'Focus',word:'blue motion'},{id:4,title:'Good Energy',artist:'Melora Studio',mood:'Energy',word:'good energy'},{id:5,title:'Slow Sunday',artist:'Melora Studio',mood:'Chill',word:'slow sunday'}];
const $=id=>document.getElementById(id);const audio=$('audio');let state={likes:[],playlists:[]};
try{const s=JSON.parse(localStorage.getItem('melora-v1')||'null');if(s&&Array.isArray(s.likes)&&Array.isArray(s.playlists)){state.likes=s.likes.filter(x=>Number.isInteger(x)&&tracks[x]);state.playlists=s.playlists.filter(p=>p&&typeof p.id==='string'&&typeof p.name==='string'&&Array.isArray(p.tracks)).slice(0,50).map(p=>({id:p.id,name:p.name.slice(0,60),tracks:p.tracks.filter(x=>Number.isInteger(x)&&tracks[x])}));}}catch{}
let page='home',mood='All',query='',current=null,queue=tracks.map(t=>t.id),shuffle=false,repeat=false,toastTimer;
function save(){try{localStorage.setItem('melora-v1',JSON.stringify(state));}catch{toast('Browser storage is unavailable. Changes last for this session.');}renderNav();}
function toast(msg){$('toast').textContent=msg;$('toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').style.display='none',3200);}
function el(tag,cls,text){const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e;}
function btn(text,label,fn,cls){const b=el('button',cls,text);b.setAttribute('aria-label',label);b.onclick=fn;return b;}
function cover(t,word=true){const e=el('div','cover c'+t.id);e.append(el('span','cover-word',word?t.word:'♪'));return e;}
function toggleLike(id){if(id===null)return;state.likes=state.likes.includes(id)?state.likes.filter(x=>x!==id):[...state.likes,id];save();render();updatePlayer();}
function renderNav(){const n=$('playlistNav');n.replaceChildren();state.playlists.forEach(p=>n.append(btn('♫  '+p.name,'Open '+p.name,()=>navigate(p.id))));}
function navigate(p){page=p;query='';render();}
function heading(title,action){const d=el('div','section-heading');d.append(el('h2','',title));if(action)d.append(btn(action.label,action.label,action.fn));return d;}
function card(t){const d=el('article','card'),c=cover(t);c.append(btn('▶','Play '+t.title,()=>playTrack(t.id), 'card-play'));d.append(c,el('h3','',t.title),el('p','',t.mood+' · Original demo'));return d;}
function rows(ids,playlist){const d=el('div','track-list');ids.forEach((id,i)=>{const t=tracks[id],r=el('div','track-row');r.append(btn(String(i+1),'Play '+t.title,()=>playTrack(id,ids),'row-index'),cover(t,false));const info=el('div');info.append(el('strong','',t.title),el('small','',t.artist));r.append(info,el('span','tag',t.mood),el('span','time','0:32'),btn(state.likes.includes(id)?'♥':'♡','Toggle like for '+t.title,()=>toggleLike(id),state.likes.includes(id)?'liked':''),btn(playlist?'−':'+',playlist?'Remove from playlist':'Add to playlist or queue',()=>playlist?removeTrack(playlist,id):addMenu(id)));d.append(r);});return d;}
function render(){const main=$('main');main.replaceChildren();document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));
if(page==='home'){
const intro=el('div','intro');intro.append(el('h2','greeting','Find your next favourite.'),el('p','muted','A little music. A better day.'));main.append(intro);
const hero=el('section','hero'),copy=el('div','hero-copy');copy.append(el('span','eyebrow','THE DAILY MIX'),el('h1','','Let the good\nvibes play.'),el('p','','Ease into your day with warm beats and mellow melodies.'),btn('▶  Play the mix','Play the daily mix',()=>playTrack(0,tracks.map(t=>t.id)),'primary'));const art=el('div','hero-art'),rec=el('div','record');rec.append(el('div','record-label','◒'));art.append(rec,el('span','float-note','♪'));hero.append(copy,art,el('span','hero-caption','CURATED FOR YOUR EVERYDAY'));main.append(hero);
const chips=el('div','chips');['All','Chill','Focus','Energy'].forEach(m=>chips.append(btn(m,'Filter '+m,()=>{mood=m;render();},'chip'+(mood===m?' selected':''))));main.append(chips,heading('Made for your mood',{label:'Explore all ↗',fn:()=>navigate('search')}));const cards=el('div','cards');tracks.filter(t=>mood==='All'||t.mood===mood).forEach(t=>cards.append(card(t)));main.append(cards,heading('A fresh rotation'),rows([4,1,3]));
}else if(page==='search'){
main.append(el('h1','greeting','Find your sound.'),el('p','muted','Search the original demo catalogue by title or mood.'));const input=el('input','searchbox');input.type='search';input.placeholder='Search songs, artists, moods…';input.value=query;input.setAttribute('aria-label','Search music');const result=el('div');const update=()=>{query=input.value;const ids=tracks.filter(t=>(t.title+' '+t.artist+' '+t.mood).toLowerCase().includes(query.toLowerCase())).map(t=>t.id);result.replaceChildren(heading(ids.length+' tracks'),ids.length?rows(ids):el('p','empty','No tracks found. Try “Chill” or “Golden”.'));};input.oninput=update;main.append(input,result);update();
}else if(page==='liked'){main.append(el('h1','greeting','Your favourites.'),el('p','muted','The songs you keep coming back to.'));main.append(state.likes.length?rows(state.likes):el('p','empty','Tap the heart beside a song to save it here.'));
}else if(page==='library'){main.append(el('h1','greeting','Your library.'),el('p','muted','A collection for every version of you.'),btn('+ Create playlist','Create playlist',newPlaylist,'primary'));main.append(heading('Your playlists'));if(!state.playlists.length)main.append(el('p','empty','Create your first playlist, then add tracks with the + button.'));state.playlists.forEach(p=>{const h=el('div','playlist-header');h.append(btn('♫  '+p.name,'Open '+p.name,()=>navigate(p.id)),el('p','muted',p.tracks.length+' tracks'));main.append(h);});
}else{const p=state.playlists.find(x=>x.id===page);if(!p){page='library';render();return;}const h=el('div','playlist-header');h.append(el('span','eyebrow','YOUR PLAYLIST'),el('h1','',p.name),el('p','muted',p.tracks.length+' tracks · Saved in this browser'));main.append(h);const actions=el('div','button-row');actions.append(btn('▶ Play playlist','Play playlist',()=>p.tracks.length?playTrack(p.tracks[0],p.tracks):toast('Add a song first.'),'primary'),btn('Rename','Rename playlist',()=>renamePlaylist(p)),btn('Delete','Delete playlist',()=>deletePlaylist(p),'danger'));main.append(actions,p.tracks.length?rows(p.tracks,p):el('p','empty','Find a song in Discover or Search, then use + to add it.'));}
main.append(el('p','bottom-note','PREVIEW CATALOGUE · Six original 32-second instrumental sketches. Your library is saved on this device.'));renderQueue();}
function modal(content){$('modalContent').replaceChildren(content);$('modal').showModal();}
function nameForm(title,value,submit){const box=el('div');box.append(el('h2','',title));const f=el('form'),input=el('input','field');input.placeholder='Playlist name';input.required=true;input.maxLength=60;input.value=value;input.setAttribute('aria-label','Playlist name');const b=el('button','primary','Save playlist');b.type='submit';f.append(input,b);f.onsubmit=e=>{e.preventDefault();const name=input.value.trim();if(!name){input.setCustomValidity('Enter a playlist name');input.reportValidity();return;}submit(name);$('modal').close();};input.oninput=()=>input.setCustomValidity('');box.append(f);modal(box);input.focus();}
function newPlaylist(){if(state.playlists.length>=50){toast('Maximum 50 playlists reached.');return;}nameForm('Create a playlist','',name=>{const p={id:crypto.randomUUID(),name,tracks:[]};state.playlists.push(p);save();navigate(p.id);});}
function renamePlaylist(p){nameForm('Rename playlist',p.name,name=>{p.name=name;save();render();});}
function deletePlaylist(p){const box=el('div');box.append(el('h2','','Delete playlist?'),el('p','muted','Remove “'+p.name+'” from this browser?'));box.append(btn('Delete playlist','Confirm delete',()=>{state.playlists=state.playlists.filter(x=>x.id!==p.id);save();$('modal').close();navigate('library');},'primary'));modal(box);}
function removeTrack(p,id){p.tracks=p.tracks.filter(x=>x!==id);save();render();}
function addMenu(id){const box=el('div');box.append(el('h2','','Add “'+tracks[id].title+'”'));box.append(btn('Add to playback queue','Add to queue',()=>{queue.push(id);renderQueue();$('modal').close();toast('Added to queue');},'modal-option'));state.playlists.forEach(p=>box.append(btn('♫  '+p.name,'Add to '+p.name,()=>{if(!p.tracks.includes(id)){p.tracks.push(id);save();toast('Added to '+p.name);}else toast('Already in this playlist');$('modal').close();},'modal-option')));box.append(btn('+ New playlist','Create playlist',()=>{$('modal').close();newPlaylist();},'modal-option'));modal(box);}
async function playTrack(id,ids){if(ids)queue=[...ids];if(!queue.includes(id))queue.push(id);current=id;audio.src='assets/track-'+id+'.wav';audio.volume=Number($('volume').value);updatePlayer();renderQueue();try{await audio.play();}catch{toast('Playback could not start. Press play to try again.');}}
function updatePlayer(){if(current===null)return;const t=tracks[current];$('trackTitle').textContent=t.title;$('trackArtist').textContent=t.artist+' · '+t.mood;$('miniCover').className='cover mini c'+current;$('playerLike').textContent=state.likes.includes(current)?'♥':'♡';$('playerLike').classList.toggle('liked',state.likes.includes(current));}
function next(direction=1){if(current===null){playTrack(queue[0]??0);return;}let at=queue.indexOf(current),id=shuffle?queue[Math.floor(Math.random()*queue.length)]:queue[(at+direction+queue.length)%queue.length];playTrack(id??0);}
function renderQueue(){const n=$('queueList');n.replaceChildren();queue.forEach((id,i)=>{const t=tracks[id],r=el('div','queue-item');r.append(cover(t,false));const text=el('div');text.append(el('strong','',t.title+(current===id?' · Playing':'')),el('small','',t.mood));r.append(text,btn('▶','Play '+t.title,()=>playTrack(id)));n.append(r);});}
function info(){const b=el('div');b.append(el('h2','','Your private listening space'),el('p','muted','Melora is a working first version with six original demo instrumentals. This hosted preview is private and requires platform sign-in.'),el('p','muted','Favourites and playlists stay in this browser. No passwords, payment details, analytics, uploads, or third-party music services are collected by this app.'),el('p','muted','Commercial music, account sync, subscriptions, and shared listening are not connected. A production launch needs a licensed catalogue and server security review.'));b.append(btn('Clear saved library','Clear saved library',()=>{const c=el('div');c.append(el('h2','','Clear this browser’s library?'),el('p','muted','This removes your saved playlists and liked songs.'),btn('Clear library','Confirm clear library',()=>{state={likes:[],playlists:[]};save();navigate('home');$('modal').close();toast('Saved library cleared');},'primary'));modalContentSwap(c);},'modal-option'));modal(b);}
function modalContentSwap(c){$('modalContent').replaceChildren(c);}
function time(s){return Math.floor(s/60)+':'+String(Math.floor(s%60)).padStart(2,'0');}
document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>navigate(b.dataset.page));$('newPlaylist').onclick=newPlaylist;$('privacy').onclick=info;$('profile').onclick=info;$('playerLike').onclick=()=>toggleLike(current);$('play').onclick=async()=>{if(current===null){playTrack(0);return;}if(audio.paused){try{await audio.play();}catch{toast('Unable to play audio.');}}else audio.pause();};$('next').onclick=()=>next();$('prev').onclick=()=>{if(audio.currentTime>3)audio.currentTime=0;else next(-1);};$('shuffle').onclick=()=>{shuffle=!shuffle;$('shuffle').setAttribute('aria-pressed',String(shuffle));$('shuffle').classList.toggle('liked',shuffle);toast(shuffle?'Shuffle on':'Shuffle off');};$('repeat').onclick=()=>{repeat=!repeat;audio.loop=repeat;$('repeat').setAttribute('aria-pressed',String(repeat));$('repeat').classList.toggle('liked',repeat);toast(repeat?'Repeat song on':'Repeat off');};$('queueToggle').onclick=()=>{$('queuePanel').hidden=!$('queuePanel').hidden;};$('closeQueue').onclick=()=>{$('queuePanel').hidden=true;};$('volume').oninput=()=>audio.volume=Number($('volume').value);$('seek').oninput=()=>{if(current!==null&&Number.isFinite(audio.duration))audio.currentTime=Number($('seek').value);};audio.onplay=()=>{$('play').textContent='Ⅱ';$('play').setAttribute('aria-label','Pause');};audio.onpause=()=>{$('play').textContent='▶';$('play').setAttribute('aria-label','Play');};audio.ontimeupdate=()=>{$('seek').value=audio.currentTime;$('elapsed').textContent=time(audio.currentTime);};audio.onloadedmetadata=()=>{$('seek').max=audio.duration;$('duration').textContent=time(audio.duration);};audio.onended=()=>next();audio.onerror=()=>toast('The audio file could not load. Please try again.');renderNav();render();
